// ❌ cache가 전역에 노출됨
var cache = {};
function factorial(x) { ... }

// ✅ cache를 함수 스코프 안에 숨김
function hideTheCache() {
    var cache = {};

    function factorial(x) {
        if (x < 2) return 1;
        if (!(x in cache)) {
            cache[x] = x * factorial(x - 1);
        }
        return cache[x];
    }

    return factorial;
}

var factorial = hideTheCache();

