title:
// ❌ FiB — 피해라
if (condition) {
    function isArray(a) { ... }
}

// ✅ function expression은 블록 안에 넣어도 됨
var isArray = function isArray(a) {
    return Array.isArray(a);
};

if (typeof Array.isArray == "undefined") {
    isArray = function isArray(a) {
        return Object.prototype.toString.call(a) == "[object Array]";
    };
}

